DELETE FROM products
WHERE prod_id = (SELECT prod_id
FROM sales WHERE time_id - 3*365 = SYSDATE);

SELECT *
FROM invoices I
JOIN customers C USING (customer_id);

SELECT D.customer.id
FROM invoices
JOIN customers C USING (C.customer_id = D.customer.id);

SELECT D.customer.id
FROM invoices
JOIN customers C USING (C.customer_id);

SELECT *
FROM invoices
JOIN customers C USING (C.customer_id);

solution:
A - SELECT *
FROM invoices I
JOIN customers C USING (customer_id);
